//! Hypothesis-test reference checks (Phase 2b) against SciPy 1.18 values in
//! `common/data2.rs` (generated by `gen/stats_ref2.py`), the NIST e-Handbook
//! generalized-ESD example, published Dixon Q tables, and a Monte Carlo
//! check of the Dixon null distribution.

mod common;
use common::data2::*;
use openstats_stats::equivalence::*;
use openstats_stats::hypothesis::{Alternative, VarianceAssumption};
use openstats_stats::normality::*;
use openstats_stats::outlier::*;
use openstats_stats::poisson::*;
use openstats_stats::proportion::*;
use openstats_stats::ttest::*;
use openstats_stats::variance::*;

fn close(got: f64, want: f64, rel: f64, what: &str) {
    let ok = if got == want {
        true
    } else if want == 0.0 {
        got.abs() <= rel
    } else {
        ((got - want) / want).abs() <= rel
    };
    assert!(ok, "{what}: got {got:e}, want {want:e}");
}

fn alt(s: &str) -> Alternative {
    match s {
        "TwoSided" => Alternative::TwoSided,
        "Less" => Alternative::Less,
        _ => Alternative::Greater,
    }
}

#[test]
fn t_tests_against_scipy() {
    for &(a, mu0, t, df, p, lo, hi) in T1 {
        let r = one_sample_t(TA, mu0, alt(a), 0.95).unwrap();
        close(r.t, t, 1e-12, "t1 t");
        close(r.df, df, 1e-15, "t1 df");
        close(r.p_value, p, 1e-10, "t1 p");
        if lo.is_finite() {
            close(r.ci.lower, lo, 1e-11, "t1 lo");
        }
        if hi.is_finite() {
            close(r.ci.upper, hi, 1e-11, "t1 hi");
        }
    }
    for &(a, pooled, d0, t, df, p, lo, hi) in T2 {
        let v = if pooled { VarianceAssumption::Pooled } else { VarianceAssumption::Welch };
        let r = two_sample_t(TA, TB, d0, v, alt(a), 0.95).unwrap();
        let w = format!("t2 {a} pooled={pooled}");
        close(r.t, t, 1e-12, &w);
        close(r.df, df, 1e-12, &w);
        close(r.p_value, p, 1e-10, &w);
        if lo.is_finite() {
            close(r.ci.lower, lo, 1e-10, &w);
        }
        if hi.is_finite() {
            close(r.ci.upper, hi, 1e-10, &w);
        }
    }
    for &(a, t, df, p, lo, hi) in TP {
        let r = paired_t(TA, TPA, 0.0, alt(a), 0.95).unwrap();
        close(r.t, t, 1e-12, "paired t");
        close(r.df, df, 1e-15, "paired df");
        close(r.p_value, p, 1e-10, "paired p");
        if lo.is_finite() {
            close(r.ci.lower, lo, 1e-10, "paired lo");
        }
        if hi.is_finite() {
            close(r.ci.upper, hi, 1e-10, "paired hi");
        }
    }
    let z = z_test(TA, 4.5, 1.5, Alternative::TwoSided, 0.95).unwrap();
    close(z.z, Z1.0, 1e-12, "z");
    close(z.p_value, Z1.1, 1e-10, "z p");
    close(z.ci.lower, Z1.3, 1e-11, "z lo");
    close(z.ci.upper, Z1.4, 1e-11, "z hi");
    close(z_test(TA, 4.5, 1.5, Alternative::Greater, 0.95).unwrap().p_value, Z1.2, 1e-10, "z p greater");
}

#[test]
fn one_proportion_against_scipy() {
    for &(x, n, p0, a, pe, lo, hi, z, zc, pn, pnc) in P1 {
        let w = format!("{x}/{n} p0={p0} {a}");
        let r = one_proportion(x, n, p0, alt(a), 0.95, false).unwrap();
        close(r.p_value_exact, pe, 1e-9, &format!("{w} exact"));
        close(r.ci_exact.lower, lo, 1e-8, &format!("{w} cp lo"));
        close(r.ci_exact.upper, hi, 1e-8, &format!("{w} cp hi"));
        close(r.z, z, 1e-12, &format!("{w} z"));
        close(r.p_value_normal, pn, 1e-10, &format!("{w} p normal"));
        let c = one_proportion(x, n, p0, alt(a), 0.95, true).unwrap();
        close(c.z, zc, 1e-12, &format!("{w} z cc"));
        close(c.p_value_normal, pnc, 1e-10, &format!("{w} p normal cc"));
    }
}

#[test]
fn two_proportions_against_reference() {
    for &(x1, n1, x2, n2, a, z, p, zc, pc, fe, lo, hi) in P2 {
        let w = format!("{x1}/{n1} vs {x2}/{n2} {a}");
        let r = two_proportions(x1, n1, x2, n2, 0.0, alt(a), 0.95, false).unwrap();
        close(r.z, z, 1e-12, &w);
        close(r.p_value_normal, p, 1e-10, &w);
        close(r.p_value_fisher.unwrap(), fe, 1e-9, &format!("{w} fisher"));
        if lo.is_finite() {
            close(r.ci.lower, lo, 1e-11, &format!("{w} ci lo"));
        }
        if hi.is_finite() {
            close(r.ci.upper, hi, 1e-11, &format!("{w} ci hi"));
        }
        let c = two_proportions(x1, n1, x2, n2, 0.0, alt(a), 0.95, true).unwrap();
        close(c.z, zc, 1e-12, &w);
        close(c.p_value_normal, pc, 1e-10, &w);
    }
}

#[test]
fn poisson_against_reference() {
    for &(x, t, r0, a, pe, lo, hi, z) in PO1 {
        let w = format!("poisson {x}/{t} r0={r0} {a}");
        let r = one_sample_poisson(x, t, r0, alt(a), 0.95).unwrap();
        close(r.p_value_exact, pe, 1e-9, &w);
        close(r.z, z, 1e-12, &w);
        close(r.ci_exact.lower, lo, 1e-9, &w);
        if hi.is_finite() {
            close(r.ci_exact.upper, hi, 1e-9, &w);
        }
    }
    for &(x1, t1, x2, t2, a, pe, lo, hi, z) in PO2 {
        let w = format!("poisson2 {x1}/{t1} vs {x2}/{t2} {a}");
        let r = two_sample_poisson(x1, t1, x2, t2, 0.0, alt(a), 0.95).unwrap();
        close(r.p_value_exact.unwrap(), pe, 1e-9, &w);
        close(r.z, z, 1e-12, &w);
        let ci = r.ci_ratio_exact.unwrap();
        close(ci.lower, lo, 1e-8, &w);
        if hi.is_finite() {
            close(ci.upper, hi, 1e-8, &w);
        }
    }
}

#[test]
fn variance_tests_against_scipy() {
    let f = f_test(VG1, VG2, 1.0, Alternative::TwoSided, 0.95).unwrap();
    close(f.f, FTEST.0, 1e-12, "F");
    close(f.p_value, FTEST.1, 1e-10, "F p");
    close(f.ci_ratio.lower, FTEST.4, 1e-10, "F ci lo");
    close(f.ci_ratio.upper, FTEST.5, 1e-10, "F ci hi");
    close(f_test(VG1, VG2, 1.0, Alternative::Less, 0.95).unwrap().p_value, FTEST.2, 1e-10, "F less");
    close(f_test(VG1, VG2, 1.0, Alternative::Greater, 0.95).unwrap().p_value, FTEST.3, 1e-10, "F greater");
    let groups = vec![VG1.to_vec(), VG2.to_vec(), VG3.to_vec()];
    for &(code, stat, d1, d2, p) in LEVENE {
        let c = match code {
            0 => Center::Mean,
            1 => Center::Median,
            _ => Center::TrimmedMean(0.1),
        };
        let r = levene_test(&groups, c).unwrap();
        close(r.statistic, stat, 1e-11, &format!("levene {code}"));
        close(r.p_value, p, 1e-9, &format!("levene {code} p"));
        assert_eq!((r.df1, r.df2), (d1, d2));
        if code == 1 {
            let b = brown_forsythe_test(&groups).unwrap();
            assert_eq!(b.statistic, r.statistic);
        }
    }
    // Bonett: cross-check of the coded formulas against an independent
    // implementation of the same published formulas (not an external tool).
    let b2 = bonett_test(&groups[..2], 0.95).unwrap();
    close(b2.statistic, B2.0, 1e-11, "bonett 2");
    close(b2.p_value, B2.1, 1e-9, "bonett 2 p");
    let b3 = bonett_test(&groups, 0.95).unwrap();
    close(b3.statistic, B3.0, 1e-11, "bonett 3");
    close(b3.p_value, B3.1, 1e-9, "bonett 3 p");
}

#[test]
fn normality_against_scipy() {
    for (k, &(x, w, p)) in SHAPIRO.iter().enumerate() {
        let r = shapiro_wilk(x).unwrap();
        close(r.w, w, 1e-9, &format!("SW {k} W"));
        // SciPy's p-value is reported to its own float precision; allow a small absolute slack
        assert!((r.p_value - p).abs() <= 1e-9 + 1e-7 * p, "SW {k} (n={}): p {} vs {p}", x.len(), r.p_value);
    }
    for (k, &(x, mu, s, d, p)) in KS.iter().enumerate() {
        let r = ks_normal(x, mu, s).unwrap();
        close(r.d, d, 1e-12, &format!("KS {k} D"));
        // SciPy's exact p-value for n = 200 is off by ~5e-6 relative: the case below
        // is pinned to a 60-digit evaluation of the Marsaglia–Tsang–Wang matrix power.
        assert!((r.p_value - p).abs() <= 1e-9 + 1e-5 * p, "KS {k} (n={}): p {} vs {p}", x.len(), r.p_value);
        if x.len() == 200 {
            close(r.p_value, 0.047957047386078820, 1e-11, "KS n=200 high-precision p");
        }
    }
    for (k, &(x, rj, p)) in RJ.iter().enumerate() {
        let r = ryan_joiner(x).unwrap();
        close(r.rj, rj, 1e-11, &format!("RJ {k} r"));
        assert!((r.p_value - p).abs() <= 1e-8, "RJ {k}: p {} vs {p}", r.p_value);
    }
}

#[test]
fn grubbs_against_formula() {
    let r = grubbs_test(GRUBBS_X, OutlierSide::Either).unwrap();
    close(r.g, GRUBBS.0, 1e-12, "G");
    close(r.p_value, GRUBBS.1, 1e-10, "G p");
    close(grubbs_critical(GRUBBS_X.len(), 0.05, OutlierSide::Either).unwrap(), GRUBBS.2, 1e-11, "G crit");
}

#[test]
fn esd_nist_handbook_example() {
    // NIST/SEMATECH e-Handbook 1.3.5.17.1 (Rosner's data): R1-3 = 3.118, 2.942, 3.179
    // against lambda1-3 = 3.158, 3.151, 3.143 → three outliers at α = 0.05.
    let r = generalized_esd(ESD_X, 10, 0.05).unwrap();
    assert_eq!(r.n_outliers, 3);
    let hb = [(3.118, 3.158), (2.942, 3.151), (3.179, 3.143)];
    for (i, &(rr, ll)) in hb.iter().enumerate() {
        assert!((r.steps[i].r - rr).abs() < 1.5e-3, "R{}: {}", i + 1, r.steps[i].r);
        assert!((r.steps[i].lambda - ll).abs() < 1.5e-3, "lambda{}: {}", i + 1, r.steps[i].lambda);
    }
    for (i, &(rr, ll)) in ESD.iter().enumerate() {
        close(r.steps[i].r, rr, 1e-11, &format!("ESD R{}", i + 1));
        close(r.steps[i].lambda, ll, 1e-11, &format!("ESD lambda{}", i + 1));
    }
    let mut vals: Vec<f64> = r.outlier_indices.iter().map(|&i| ESD_X[i]).collect();
    vals.sort_by(|a, b| a.total_cmp(b));
    assert_eq!(vals, vec![5.34, 5.42, 6.01]);
}

#[test]
fn dixon_critical_values_match_published_tables() {
    // Dixon/Dean–Dixon Q tables (r10, n = 3..10). One-sided tail α corresponds to
    // the "confidence 1 − 2α" column of the usual tables.
    let q90 = [0.941, 0.765, 0.642, 0.560, 0.507, 0.468, 0.437, 0.412];
    let q95 = [0.970, 0.829, 0.710, 0.625, 0.568, 0.526, 0.493, 0.466];
    let q99 = [0.994, 0.926, 0.821, 0.740, 0.680, 0.634, 0.598, 0.568];
    for (i, n) in (3..=10).enumerate() {
        for (tab, a) in [(&q90, 0.05), (&q95, 0.025), (&q99, 0.005)] {
            let c = dixon_q_critical(n, a, true).unwrap();
            // Printed tables are rounded and a few entries (e.g. n = 4 at 99 %: .926 vs .9207)
            // are slightly off; the Monte Carlo test below checks the computed values themselves.
            assert!((c - tab[i]).abs() < 0.006, "n={n} alpha={a}: computed {c:.4}, table {}", tab[i]);
        }
    }
    // two-sided (either end) at alpha = 0.10 is the same as one-sided 0.05
    assert_eq!(dixon_q_critical(7, 0.10, false).unwrap(), dixon_q_critical(7, 0.05, true).unwrap());
}

#[test]
fn dixon_critical_values_match_monte_carlo() {
    use openstats_math::dist::{ContinuousDistribution, Normal};
    use openstats_math::random::Pcg64;
    let z = Normal::standard();
    let mut rng = Pcg64::with_stream(2026, 3);
    for (n, alpha) in [(4usize, 0.005), (6, 0.05), (8, 0.025), (12, 0.05)] {
        let crit = dixon_q_critical(n, alpha, true).unwrap();
        let reps = 400_000u32;
        let mut hits = 0u32;
        for _ in 0..reps {
            let mut x: Vec<f64> = (0..n).map(|_| z.sample(&mut rng)).collect();
            x.sort_by(|a, b| a.total_cmp(b));
            if (x[n - 1] - x[n - 2]) / (x[n - 1] - x[0]) > crit {
                hits += 1;
            }
        }
        let mc = f64::from(hits) / f64::from(reps);
        let se = (alpha * (1.0 - alpha) / f64::from(reps)).sqrt();
        assert!((mc - alpha).abs() < 5.0 * se, "n={n}: Monte Carlo tail {mc} at the critical value, want {alpha}");
    }
}

#[test]
fn tost_against_scipy() {
    for &(kind, lo, hi, est, se, df, pl, pu, cl, ch) in TOST {
        let r = match kind {
            0 => tost_one_sample(TA, 4.5, lo, hi, 0.05),
            1 => tost_two_sample(TA, TB, lo, hi, VarianceAssumption::Welch, 0.05),
            2 => tost_two_sample(TA, TB, lo, hi, VarianceAssumption::Pooled, 0.05),
            _ => tost_paired(TA, TPA, lo, hi, 0.05),
        }
        .unwrap();
        let w = format!("tost kind {kind}");
        close(r.estimate, est, 1e-12, &w);
        close(r.se, se, 1e-12, &w);
        close(r.df, df, 1e-12, &w);
        close(r.p_lower, pl, 1e-10, &w);
        close(r.p_upper, pu, 1e-10, &w);
        close(r.ci.lower, cl, 1e-11, &w);
        close(r.ci.upper, ch, 1e-11, &w);
        assert_eq!(r.equivalent, pl.max(pu) < 0.05);
    }
}
